package com.aoo.bcg.poker;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ComparePokerEngineTest{@Test void betsComparesAndNeverLeaksOtherPrivateCards(){var state=new ComparePokerState(Map.of(0,new ComparePokerSeat(10,List.of(103,104,105),100,0,false,false),1,new ComparePokerSeat(11,List.of(106,107,108),100,0,false,false)),0,0,false,null);var engine=new ComparePokerEngine();state=engine.bet(state,0,10);assertEquals(10,state.pot());var own=engine.viewFor(state,10);assertEquals(3,own.seats().get(0).visibleCards().size());assertTrue(own.seats().get(1).visibleCards().isEmpty());state=engine.compare(state,1,0,Comparator.comparingInt(cards->cards.stream().mapToInt(StandardPokerRuleSet::rank).sum()));assertTrue(state.finished());assertEquals(1,state.winnerSeat());}}
